{{pins}}
void setup() {
  pinMode(LED_GREEN, OUTPUT);   // the GO light
  pinMode(LED_RED, OUTPUT);     // player 1's light
  pinMode(LED_YELLOW, OUTPUT);  // player 2's light
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(BUTTON2_PIN, INPUT_PULLUP);
  Serial.begin(9600);
  randomSeed(analogRead(0));
}

void winner(int player, int lightPin) {
  digitalWrite(LED_GREEN, LOW);
  digitalWrite(lightPin, HIGH);
  tone(BUZZER_PIN, 1500, 400);
  Serial.print("Player ");
  Serial.print(player);
  Serial.println(" wins!");
  delay(3000);
  digitalWrite(lightPin, LOW);
}

void loop() {
  Serial.println("Get ready...");
  delay(random(2000, 5000));
  // Pressing before the light is a false start.
  if (digitalRead(BUTTON_PIN) == LOW || digitalRead(BUTTON2_PIN) == LOW) {
    Serial.println("Too soon! Try again.");
    tone(BUZZER_PIN, 200, 500);
    delay(2000);
    return;
  }
  digitalWrite(LED_GREEN, HIGH);
  tone(BUZZER_PIN, 1000, 100);
  while (true) {
    if (digitalRead(BUTTON_PIN) == LOW) {
      winner(1, LED_RED);
      return;
    }
    if (digitalRead(BUTTON2_PIN) == LOW) {
      winner(2, LED_YELLOW);
      return;
    }
  }
}
